// clients/ui/src/screens/media_warm.ts — lazy media-prefetch runtime.
// Kept out of the startup bundle: feed/viewer import it asynchronously as soon as media becomes useful.
import type { Message } from "./types.ts";
import type { MediaPort } from "./media.ts";
import {
  attachmentView,
  autoDownloadDecision,
  type AutoDownloadPolicy,
  type NetworkType,
} from "./media_model.ts";

export interface MediaWarmTarget {
  fileId: number;
  mime?: string;
}

export interface MediaWarmQueue {
  enqueue(targets: readonly MediaWarmTarget[]): void;
  destroy(): void;
}

export interface MediaPrefetchContext {
  policy: AutoDownloadPolicy;
  network: NetworkType;
  dataSaver: boolean;
}

export interface MediaPrefetchItem {
  fileId: number;
  mime: string;
}

// Warm bytes through the canonical MediaCache without retaining disposable blob URLs. Concurrent calls
// for the same file are coalesced before they reach the cache; failed targets remain retryable.
export function createMediaWarmQueue(
  media: Pick<MediaPort, "objectUrl" | "revoke">,
  concurrency = 4,
): MediaWarmQueue {
  const limit = Math.max(1, Math.min(8, Math.floor(concurrency) || 1));
  const queued: MediaWarmTarget[] = [];
  const known = new Set<number>();
  let active = 0;
  let destroyed = false;

  const drain = (): void => {
    if (destroyed) return;
    while (active < limit && queued.length > 0) {
      const target = queued.shift()!;
      active += 1;
      void media.objectUrl(target.fileId, target.mime).then((url) => {
        media.revoke(url);
      }).catch(() => {
        known.delete(target.fileId);
      }).finally(() => {
        active -= 1;
        drain();
      });
    }
  };

  return {
    enqueue(targets) {
      if (destroyed) return;
      for (const target of targets) {
        if (!Number.isSafeInteger(target.fileId) || target.fileId <= 0 || known.has(target.fileId)) continue;
        known.add(target.fileId);
        queued.push(target);
      }
      drain();
    },
    destroy() {
      destroyed = true;
      queued.length = 0;
      known.clear();
    },
  };
}

// Resolve unique inline blobs that should be warmed before the DOM asks for them. Optimised feed
// variants win over source files; the full-resolution viewer warms its own neighbours separately.
export function inlineMediaPrefetchItems(
  messages: readonly Message[],
  context: MediaPrefetchContext,
): MediaPrefetchItem[] {
  const seen = new Set<number>();
  const out: MediaPrefetchItem[] = [];
  for (const message of messages) {
    if (message.deleted) continue;
    const attachment = attachmentView(message);
    if (!attachment) continue;
    const blurred = attachment.spoiler || attachment.viewOnce || attachment.sensitive;
    if (!autoDownloadDecision({
      policy: context.policy,
      network: context.network,
      kind: attachment.kind,
      sizeBytes: attachment.size,
      dataSaver: context.dataSaver,
      blurred,
    })) continue;
    const fileId = attachment.meta.feedFileId ?? attachment.fileId;
    if (seen.has(fileId)) continue;
    seen.add(fileId);
    out.push({ fileId, mime: attachment.mime });
  }
  return out;
}

const SHARED = new WeakMap<object, MediaWarmQueue>();

function sharedQueue(media: Pick<MediaPort, "objectUrl" | "revoke">): MediaWarmQueue {
  const key = media as object;
  const current = SHARED.get(key);
  if (current) return current;
  const next = createMediaWarmQueue(media, 4);
  SHARED.set(key, next);
  return next;
}

export function prefetchInlineMedia(
  media: Pick<MediaPort, "objectUrl" | "revoke">,
  messages: readonly Message[],
  context: MediaPrefetchContext,
): void {
  sharedQueue(media).enqueue(inlineMediaPrefetchItems(messages, context));
}

export function prefetchMediaTargets(
  media: Pick<MediaPort, "objectUrl" | "revoke">,
  targets: readonly MediaWarmTarget[],
): void {
  sharedQueue(media).enqueue(targets);
}

export function destroyMediaPrefetch(media: Pick<MediaPort, "objectUrl" | "revoke">): void {
  const key = media as object;
  SHARED.get(key)?.destroy();
  SHARED.delete(key);
}
